-- Schema of human-bridge/bridge.db at tag v3.261113.2, generated by src/bridge/store.ts getBridgeStore()
-- against a newly created, isolated RAVI_STATE_DIR. Never a copy of a production database.

CREATE TABLE approvals(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, turn_id TEXT NOT NULL,
        capability TEXT NOT NULL, description TEXT NOT NULL, action_digest TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1,
        expires_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending');

CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, enrollment_id TEXT,
        subject TEXT, request_id TEXT, operation TEXT NOT NULL, target TEXT, result TEXT NOT NULL);

CREATE TABLE conversations(id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL, subject TEXT NOT NULL,
        project_id TEXT NOT NULL, agent_id TEXT NOT NULL, session_name TEXT UNIQUE NOT NULL, session_key TEXT UNIQUE NOT NULL,
        title TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);

CREATE TABLE delegation_heads(enrollment_id TEXT NOT NULL, subject TEXT NOT NULL, project_id TEXT NOT NULL,
        revision INTEGER NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(enrollment_id,subject,project_id));

CREATE TABLE enrollments(id TEXT PRIMARY KEY, document TEXT NOT NULL);

CREATE TABLE events(conversation_id TEXT NOT NULL, sequence INTEGER NOT NULL, type TEXT NOT NULL,
        data TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(conversation_id,sequence));

CREATE TABLE gateway_receipts(enrollment_id TEXT NOT NULL,subject TEXT NOT NULL,operation_id TEXT NOT NULL,
        digest TEXT NOT NULL,status INTEGER,body TEXT,PRIMARY KEY(enrollment_id,subject,operation_id));

CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id),
        role TEXT NOT NULL, text TEXT NOT NULL, turn_id TEXT NOT NULL, created_at INTEGER NOT NULL);

CREATE TABLE receipts(enrollment_id TEXT NOT NULL, subject TEXT NOT NULL, request_id TEXT NOT NULL,
        digest TEXT NOT NULL, result TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(enrollment_id,subject,request_id));

CREATE TABLE replays(jti TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);

CREATE TABLE state_schema_versions (component TEXT PRIMARY KEY, version TEXT NOT NULL);

CREATE TABLE turns(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id),
        status TEXT NOT NULL, cancel_requested INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL, authority TEXT NOT NULL, created_at INTEGER NOT NULL);

CREATE UNIQUE INDEX active_turn ON turns(conversation_id) WHERE status IN ('queued','running','awaiting_approval');
